def perimeter(width: float, height: float) -> float:
    """Return the perimeter of a width by height rectangle."""
    return 2 * (width + height)


def shout(text: str) -> str:
    """Return text in capital letters with an exclamation mark."""
    return text.upper() + "!"


def whisper(text: str):
    pass


print(perimeter(3, 4))
print(perimeter(2.5, 1.5))
print(shout("hello"))
print(shout("go team"))

