def min_max(nums: list[int]):
    """Return the smallest and largest number, or None, None if empty."""
    if not nums:
        return None, None
    smallest = largest = nums[0]
    for n in nums[1:]:
        if n < smallest:
            smallest = n
        elif n > largest:
            largest = n
    return smallest, largest


def show_title(title: str):
    print(f"== {title} ==")


low, high = min_max([4, 9, 1])
print(f"min {low}, max {high}")
low, high = min_max([])
print(f"min {low}, max {high}")
result = show_title("Report")
print(result)

