def count_and_average(nums: list[int]):
    """Return how many numbers there are and their average."""
    if not nums:
        return 0, 0.0
    return len(nums), sum(nums) / len(nums)


def announce(text: str):
    print(f"Note: {text}")


count, average = count_and_average([3, 4, 8])
print(f"count {count}, average {average:.2f}")
count, average = count_and_average([])
print(f"count {count}, average {average:.2f}")
result = announce("all done")
print(result)
